def semver_sort(versions):
    def parse_key(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_key = (1,)  # no prerelease sorts after
        else:
            idents = pre.split('.')
            parts = []
            for ident in idents:
                if ident.isdigit():
                    parts.append((0, int(ident), ''))
                else:
                    parts.append((1, 0, ident))
            pre_key = (0, len(idents), tuple(parts))
        return (major, minor, patch, pre_key)

    return sorted(versions, key=parse_key)

